 "content": "def transform(grid):
    """Collapse consecutive duplicate rows and columns."""
    rows = []
    for row in grid:
        row = list(row)
        if not rows or row != rows[-1]:
            rows.append(row)
    if not rows:
        return []
    keep_cols = []
    for c in range(len(rows[0])):
        col = tuple(row[c] for row in rows)
        if not keep_cols or col != keep_cols[-1]:
            keep_cols.append(col)
    return [[row[c] for c in range(len(rows[0])) if c == 0 or tuple(r[c] for r in rows) != tuple(r[c-1] for r in rows)] for row in rows]
